-- 450_hidden_curated_2.sql — #450 Sacramento story batch, part 2: 12 HIDDEN storyless OSM pins brought back with a story (drafted 2026-11-02).
-- Same shape and rules as 450_hidden_curated.sql: exact stored name at the stored coordinate (the WWI memorial's stored name keeps
-- OSM's "Memoral" spelling on purpose — the row must match the pin), read from the stored places:v34 rows. These are the gate
-- rescues (FROM PITTSBURGH (7)): the gate dry run (42 tiles, 44 resolved / 866 dropped) unioned with 450_leads_sacramento.tsv,
-- verdicts in 450_gate_drops_sacramento.tsv. Each pin is hidden in the live serve, has no served pin of the same subject within
-- 150 m, and passed #542 by pin id. Sources: an HMdb marker 0–23 m from the pin, or the subject's own article (the Indian
-- Museum; Alkali Flat Central, the district article's core). Batch file — run in the Mac session after the seed commit and
-- after 450_hidden_curated.sql, then curated_category_backfill(true); every row should report dist_m 0.
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Bishop Alfonso Gallegos$t$, 38.5786101::double precision, -121.4926861::double precision, $t$This statue honors Alfonso Gallegos (1931–1991), an Augustinian Recollect priest ordained in 1958 who in 1981 became the first Hispanic bishop of Sacramento, remembered as a champion of education, a friend of the poor and a voice for children.$t$, $t$https://www.hmdb.org/m.asp?m=137648$t$, $t$#450 hidden-pin row: osm_node7217498885, stored in 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$California Firefighters Memorial$t$, 38.5755572::double precision, -121.4903711::double precision, $t$This Capitol Park memorial honors California's firefighters who gave their lives protecting the lives, families and homes of the people they served.$t$, $t$https://www.hmdb.org/m.asp?m=14836$t$, $t$#450 hidden-pin row: osm_node7217498985, stored in 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$California Peace Officers Memorial$t$, 38.576772::double precision, -121.495316::double precision, $t$Raised by fellow officers and concerned Californians, this memorial honors the California peace officers who have died in the line of duty since statehood to keep their communities peaceful and orderly.$t$, $t$https://www.hmdb.org/m.asp?m=14814$t$, $t$#450 hidden-pin row: osm_node4357111342, stored in 771_-2430, 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$California Vietnam Veterans Memorial$t$, 38.5756801::double precision, -121.4886503::double precision, $t$This memorial honors the Californians who died or remain missing in the Vietnam War, 1959–1975, and everyone who served in it; its bronze figures are by Rolf Kriken, realizing the dream of 1st Cavalry veteran Herman Woods.$t$, $t$https://www.hmdb.org/m.asp?m=137482$t$, $t$#450 hidden-pin row: osm_node358836771, stored in 771_-2430, 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$Navigator Monument$t$, 38.5592012::double precision, -121.26189::double precision, $t$Set up for the 75 years of Mather Air Force Base, this monument is a tribute to the navigators who trained at Mather, who set their crews' course, completed the mission and brought them home.$t$, $t$https://www.hmdb.org/m.asp?m=57287$t$, $t$#450 hidden-pin row: osm_node1641431430, stored in 771_-2425, 771_-2426; containing tile 771_-2425 stores it (#542)$t$),
  ($t$Pony Express Monument$t$, 38.5832538::double precision, -121.5039311::double precision, $t$The Pony Express started here at 2:45 a.m. on April 4, 1860, when Sam Hamilton rode into a rainstorm on the first leg of the 1,966-mile run to St. Joseph, Missouri; in its 18 months, riders on 500 ponies carried 35,000 pieces of mail and lost only one pouch.$t$, $t$https://www.hmdb.org/m.asp?m=11326$t$, $t$#450 hidden-pin row: osm_node358836111, stored in 771_-2430, 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$Sacramento County WWI Veterans Memoral$t$, 38.5369617::double precision, -121.4934162::double precision, $t$Sacramento County raised this memorial to its people who served in World War I, 1914–1918, and carved on it the names of those who gave their lives.$t$, $t$https://www.hmdb.org/m.asp?m=91485$t$, $t$#450 hidden-pin row: osm_way342629810, stored in 770_-2430, 771_-2429, 771_-2430; containing tile 771_-2430 stores it (#542)$t$),
  ($t$State Indian Museum (SHP)$t$, 38.5730354::double precision, -121.471727::double precision, $t$Run by California State Parks at 2618 K Street, this museum presents the cultures of California's first peoples, more than 150 distinct tribal groups who spoke at least 64 languages.$t$, $t$https://en.wikipedia.org/wiki/California_State_Indian_Museum$t$, $t$#450 hidden-pin row: osm_way40186321, stored in 771_-2429, 771_-2430, 772_-2429, 772_-2430; containing tile 771_-2429 stores it (#542)$t$),
  ($t$Theodore Judah Monument$t$, 38.5809127::double precision, -121.5049381::double precision, $t$Southern Pacific's employees put up this monument in 1930 to Theodore Judah, who in 1860 convinced four Sacramento merchants to back his railroad; ground was broken in 1863, Judah died that November, and the line he surveyed over the Sierra met the Union Pacific at Promontory in 1869.$t$, $t$https://www.hmdb.org/m.asp?m=11735$t$, $t$#450 hidden-pin row: osm_node358836117, stored in 771_-2430, 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$Thomas Starr King$t$, 38.576326::double precision, -121.4916248::double precision, $t$Thomas Starr King, the San Francisco Unitarian minister called the Apostle of Liberty, is credited with keeping California in the Union at the start of the Civil War; his statue welcomes visitors to the Civil War Memorial Grove, Capitol Park's first monument, dedicated in 1897.$t$, $t$https://www.hmdb.org/m.asp?m=90267$t$, $t$#450 hidden-pin row: osm_node5370737515, stored in 771_-2430, 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$U.S.S. California$t$, 38.5762128::double precision, -121.4917713::double precision, $t$This is the bell of the USS California, the only battleship built on the Pacific Coast, launched at Mare Island in 1919; after Pearl Harbor, Leyte Gulf and Okinawa, Governor Earl Warren rang it for the last time when it was dedicated here in 1949.$t$, $t$https://www.hmdb.org/m.asp?m=70035$t$, $t$#450 hidden-pin row: osm_node7217498886, stored in 772_-2430; containing tile 772_-2430 stores it (#542)$t$),
  ($t$Alkali Flat Central Historic District$t$, 38.5846273::double precision, -121.4913441::double precision, $t$Alkali Flat is Sacramento's oldest surviving neighborhood, its first homes built between 1853 and 1869 by the city's upper class; Irish and Mexican immigrants moved in by the 1920s, when the white alkali that floods left on the ground gave it its name.$t$, $t$https://en.wikipedia.org/wiki/Alkali_Flat_Historic_District$t$, $t$#450 hidden-pin row: osm_node358836500, stored in 771_-2430, 772_-2429, 772_-2430; containing tile 772_-2430 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
